#include <iostream>
#include <vector>
#include <ranges>
#include <algorithm>
#include <numeric>

int main() {
    using namespace std;
    unsigned N, X;
    cin >> N >> X;

    vector<pair<unsigned, unsigned>> teeth(N);
    for (auto&& [U, D] : teeth)
        cin >> U >> D;

    const auto check{[X, &teeth](const unsigned H) {
        // 上の歯が存在できる区間が空にならないか調べる
        unsigned interval_L{}, interval_R{H};
        for (const auto& [U, D] : teeth) {
            // 直前の区間を [L, R] として
            // - 距離が X 以下 : [L - X, R + X]
            // - 削ってできる : [H - D, U]
            // の共通部分が求めるもの
            interval_L = max({interval_L + D, H + X, X + D}) - X - D;
            interval_R = min(interval_R + X, U);

            // 空になったら false
            if (interval_L > interval_R)
                return false;
        }
        return true;
    }};

    // H は U[i] + D[i] より大きくはできない
    unsigned R{ranges::min(teeth | views::transform([](const auto& tooth) { return tooth.first + tooth.second; })) + 1};
    // H が X 以下かつすべての U[i] + D[i] 以下ならかならず条件を満たす
    unsigned L{min(X, R - 1)};

    while (L + 1 < R) {
        const auto M{(L + R) / 2};
        (check(M) ? L : R) = M;
    }

    // ∑ (U[i] + D[i]) - LN が答え
    cout << transform_reduce(begin(teeth), end(teeth), 0UL, plus{}, [](const auto& tooth) { return tooth.first + tooth.second; }) - static_cast<unsigned long>(L) * N << endl;
    return 0;
}

#include <iostream>

int main() {
    using namespace std;
    unsigned N, X;
    cin >> N >> X;

    unsigned long sum{};
    unsigned height{2000000000}, u{1000000000}, d{1000000000};
    for (unsigned i{}, U, D; i < N; ++i) {
        cin >> U >> D;
        sum += U;
        sum += D;
        u = min(u + X, U);
        d = min(d + X, D);
        height = min(height, u + d);
    }

    cout << sum - static_cast<unsigned long>(height) * N << endl;
    return 0;
}
